@page "/board"
@using sv_275bad7dae794ea294193adca710c246.Services
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else if (allTasks is null)
{
    <p><em>Loading board…</em></p>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="board-stats">
        <span class="stat-item">Total: <strong>@allTasks.Count</strong></span>
        <span class="stat-item">To Do: <strong>@GetColumnTasks("To Do").Count</strong></span>
        <span class="stat-item">In Progress: <strong>@GetColumnTasks("In Progress").Count</strong></span>
        <span class="stat-item">Done: <strong>@GetColumnTasks("Done").Count</strong></span>
        <span class="stat-item stat-overdue">Overdue: <strong>@allTasks.Count(t => t.DueDate < DateTime.Today)</strong></span>
    </div>

    <!-- Search Bar -->
    <div class="board-search">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-columns">
        @foreach (var status in columns)
        {
            var columnTasks = GetFilteredColumnTasks(status);
            <div class="board-column">
                <div class="column-header">
                    <h3>@status</h3>
                    <span class="badge bg-secondary">@columnTasks.Count</span>
                </div>

                <div class="column-body">
                    @foreach (var task in columnTasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @{ var colIndex = Array.IndexOf(columns, status); }
                                @if (colIndex > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTaskAsync(task.Id, columns[colIndex - 1])">
                                        ← Move Left
                                    </button>
                                }
                                @if (colIndex < columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTaskAsync(task.Id, columns[colIndex + 1])">
                                        Move Right →
                                    </button>
                                }
                            </div>
                        </div>
                    }
                </div>

                @if (addingToColumn == status)
                {
                    <div class="add-task-form">
                        <input type="text" class="form-control mb-1" placeholder="Title"
                               @bind="newTitle" />
                        <input type="text" class="form-control mb-1" placeholder="Assignee"
                               @bind="newAssignee" />
                        <select class="form-select mb-1" @bind="newPriority">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" class="form-control mb-1" @bind="newDueDate" />
                        <div class="d-flex gap-1">
                            <button class="btn btn-sm btn-primary" @onclick="SaveNewTaskAsync">Save</button>
                            <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-sm btn-outline-primary add-task-btn"
                            @onclick="() => StartAdd(status)">
                        + Add Task
                    </button>
                }
            </div>
        }
    </div>
}

@code {
    private static readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem>? allTasks;
    private string? errorMessage;
    private string searchText = string.Empty;

    // New-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        allTasks!.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        allTasks!
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(searchText) ||
                         t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks!.First(t => t.Id == taskId);
            allTasks![allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today;
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            allTasks!.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

